const sum=x=>x.thin+x.thick;
export function dailyStatus(r){if(r.overflow)return {tone:'red',label:'Check oven inputs'};if(r.cureConflict)return {tone:'red',label:'Cure deadline conflict'};if(r.manualPlan?.issues.length)return {tone:'red',label:'Manual plan conflict'};if(r.holiday)return {tone:'amber',label:'Holiday · forming & WJ off'};if(r.closed)return {tone:'amber',label:'Planned shutdown'};return sum(r.backlog)>.005?{tone:'red',label:'Off pace'}:{tone:'green',label:'On pace'}}
export function weekStatus(w){if(w.overflow)return {tone:'red',label:'Check oven inputs'};if(w.cureConflict)return {tone:'red',label:'Cure deadline conflict'};if(w.manualConflict)return {tone:'red',label:'Manual plan conflict'};if(w.partial)return sum(w.backlog)>.005?{tone:'amber',label:'At risk · partial week'}:{tone:'green',label:'On pace · partial week'};return sum(w.backlog)>.005?{tone:'red',label:'Off schedule'}:{tone:'green',label:'On track'}}
export function summarize(rows){const weeks=[];for(const r of rows){let w=weeks.at(-1);if(!w||w.key!==r.key){w={key:r.key,start:r.date,end:r.date,demand:{thin:0,thick:0},out:{thin:0,thick:0},used:{thin:0,thick:0},closed:0,overflow:false,cureConflict:false};weeks.push(w)}for(const k of ['thin','thick'])for(const metric of ['demand','out','used'])w[metric][k]+=r[metric][k];w.end=r.date;w.inv=r.inv;w.backlog=r.backlog;w.closed+=+r.closed;w.overflow||=r.overflow;w.cureConflict||=r.cureConflict;w.manualConflict||=!!r.manualPlan?.issues.length;}
for(const w of weeks){w.partial=new Date(w.start+'T12:00Z').getUTCDay()!==1||new Date(w.end+'T12:00Z').getUTCDay()!==0;w.status=weekStatus(w)}
return {weeks,off:weeks.filter(w=>w.status.tone==='red'),risk:weeks.filter(w=>w.status.tone==='amber'),good:weeks.filter(w=>w.status.tone==='green'),firstRisk:rows.find(r=>dailyStatus(r).tone==='red'),last:rows.at(-1)};}
